def get_user(uid):
    key = f"user:{uid}"
    hit = redis.get(key)
    if hit:
        return json.loads(hit)
    user = db.fetch_user(uid)
    redis.setex(key, 300, json.dumps(user))
    return user

def update_user(uid, data):
    db.update_user(uid, data)
    redis.delete(f"user:{uid}")
